* BRDS -- Browse the records a KSDS file.
* Copied from 'CONS1'.
MAP BRDS1 SIZE 24x80
  FIELD AT 0,0  LEN 26 PROT BRIGHT COLOR=BLUE   "KSDS Record Browser (BRDS)"
  INPUT TERMID  AT 0,65 LEN 8  PROT COLOR=BLUE
  FIELD AT 0,60 LEN 5  PROT COLOR=BLUE          "TERM="
  FIELD AT 4,0  LEN 5  PROT                     "File:"
  INPUT FNAME   AT 4,8  LEN 16 UNDERSCORE COLOR=GREEN
  STOP          AT 4,25
  FIELD AT 4,27  LEN 10 PROT                     "Start Key:"
  INPUT STARTKEY AT 4,39 LEN 16 UNDERSCORE COLOR=GREEN
  STOP          AT 4,57
  FIELD AT 6,0  LEN 4 PROT COLOR=BLUE           "Key:"
  INPUT LASTKEY AT 6,8  LEN 12 PROT BRIGHT COLOR=GREEN
  FIELD AT 8,0  LEN 12 PROT COLOR=BLUE          "Record:"
  INPUT LASTREC AT 10,0 LEN 79 PROT BRIGHT COLOR=GREEN
  INPUT MSG     AT 18,0 LEN 78 PROT BRIGHT COLOR=RED
  FIELD AT 22,0 LEN 60 PROT COLOR=BLUE          "ENTER=Read  PF3=Exit  PF5=Reset  PF7=Previous  PF8=Next"
  CURSOR        AT FNAME
ENDMAP
